188	                        notificationService,
189	                        orderService
190	                ))
191	                .writer(shipmentJpaItemWriter())
192	                .faultTolerant()
193	                .skip(Exception.class)
194	                .skipLimit(SKIP_LIMIT)
195	                .listener(shipmentSkipListener())
196	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
197	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
198	                .build();
199	    }
