201	    /**
202	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
203	     */
204	    @Bean
205	    @StepScope
206	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
207	        log.debug("배송 상태 업데이트 ItemReader 구성");
208	        return new JpaPagingItemReaderBuilder<OrderShipment>()
209	                .name("shipmentItemReader")
210	                .entityManagerFactory(entityManagerFactory)
211	                .pageSize(CHUNK_SIZE)
212	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
213	                .build();
214	    }
