216	    /**
217	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
218	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
219	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
220	     */
221	    @Bean
222	    @StepScope
223	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
224	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
225	
226	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
227	        return orderShipment -> {
228	            String trackingNumber = orderShipment.getTrackingNumber();
229	            Long shipmentId = orderShipment.getId();
230	
231	            if (trackingNumber == null || trackingNumber.isBlank()) {
232	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
233	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
234	            }
235	
236	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
237	                    shipmentId, trackingNumber, orderShipment.getStatus());
238	
239	            try {
240	                // 2-1) 현재 상태 가져오기
241	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
242	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
243	
244	                // 2-2) 매핑
245	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
246	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
247	
248	                // 현재 상태와 동일한 경우 중복 처리 방지
249	                if (orderShipment.getStatus() == newStatus) {
250	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
251	                            shipmentId, newStatus);
252	                    return orderShipment;
253	                }
254	
255	                // 2-3) 상태에 따른 처리
256	                if (newStatus == ShipmentStatus.DELIVERED) {
257	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
258	                            shipmentId, orderShipment.getOrder().getId());
259	
260	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
261	                    // Order 상태도 COMPLETED 로 변경
262	                    orderService.completeOrder(orderShipment.getOrder().getId());
263	                    // 알림 발송
264	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
265	                }
266	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
267	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
268	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
269	                    // 필요시 알림, 로직 추가
270	                }
271	                else {
272	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
273	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
274	                }
275	
276	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
277	                return orderShipment; // Writer로 넘김
278	
279	            } catch (Exception e) {
280	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
281	                        shipmentId, trackingNumber, e.getMessage(), e);
282	
283	                // ShipmentException 타입이 아닌 경우 래핑
284	                if (!(e instanceof ShipmentException)) {
285	                    throw new ShipmentException(
286	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
287	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
288	                            e
289	                    );
290	                }
291	                throw e;
292	            }
293	        };
294	    }
295	
296	    /**
297	     * CJ대한통운 배송 상태 조회를 위한 메서드
298	     *
299	     * @param trackingNumber 운송장 번호
300	     * @return 배송 상태 텍스트
301	     * @throws Exception 조회 실패 시 발생
302	     */
303	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
304	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
305	
306	        try {
307	            // 예시: 로직 단순화
308	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
309	            Document doc = Jsoup.connect(url).get();
310	            // tbody#statusDetail 의 마지막 tr => 5번째 td
311	            Elements rows = doc.select("tbody#statusDetail tr");
312	            if (rows.isEmpty()) {
313	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
314	                throw new ShipmentException(
315	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
316	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
317	                );
318	            }
319	
320	            String status = rows.last().select("td").get(4).text();
321	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
322	            return status;
323	
324	        } catch (Exception e) {
325	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
326	
327	            if (e instanceof ShipmentException) {
328	                throw e;
329	            }
330	
331	            throw new ShipmentException(
332	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
333	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
334	                    e
335	            );
336	        }
337	    }
338	
339	    /**
340	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
341	     *
342	     * @param statusText 배송사 상태 텍스트
343	     * @return 매핑된 ShipmentStatus
344	     */
345	    private ShipmentStatus mapToShipmentStatus(String statusText) {
346	        return switch (statusText) {
347	            case "배송완료" -> ShipmentStatus.DELIVERED;
348	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
349	            default -> ShipmentStatus.IN_TRANSIT;
350	        };
351	    }
