394	                            item.getId(),
395	                            item.getTrackingNumber(),
396	                            item.getStatus(),
397	                            t.getMessage(),
398	                            t);
399	                } else {
400	                    log.error("[SkipWrite] 배송 상태 저장 스킵: item=null, 사유={}", t.getMessage(), t);
