442	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
443	    private static final int TIMEOUT_MS = 30000; // 30초
444	
445	    /**
446	     * 배송 상태 처리기 생성자
447	     *
448	     * @param browserManager Playwright 브라우저 관리자
449	     * @param notificationService 알림 서비스
450	     * @param orderService 주문 서비스
