462	    /**
463	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
464	     *
465	     * @param orderShipment 처리할 배송 정보
466	     * @return 업데이트된 배송 정보
467	     * @throws Exception 처리 중 오류 발생 시
468	     */
469	    @Override
470	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
471	        String trackingNumber = orderShipment.getTrackingNumber();
472	        Long shipmentId = orderShipment.getId();
473	
474	        if (trackingNumber == null || trackingNumber.isBlank()) {
475	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
476	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
477	        }
478	
479	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
480	                shipmentId, trackingNumber, orderShipment.getStatus());
481	
482	        Page page = null;
483	        try {
484	            // browserManager를 통해 페이지 생성
485	            page = browserManager.newPage();
486	            if (page == null) {
487	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
488	            }
489	
490	            // 타임아웃 설정
491	            page.setDefaultTimeout(TIMEOUT_MS);
492	
493	            // 배송 추적 URL로 이동
494	            String url = TRACKING_URL_PREFIX + trackingNumber;
495	            log.debug("배송 조회 페이지로 이동: {}", url);
496	            page.navigate(url);
497	
498	            // 배송 상태 테이블 로드 대기
499	            log.debug("배송 상태 테이블 로드 대기");
500	            page.waitForSelector(STATUS_SELECTOR);
501	
502	            // 최종 HTML 가져오기
503	            String renderedHtml = page.content();
504	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
505	
506	            // HTML 파싱하여 배송 상태 추출
507	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
508	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
509	
510	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
511	                    shipmentId, statusText, newStatus);
512	
513	            // 현재 상태와 동일한 경우 중복 처리 방지
514	            if (orderShipment.getStatus() == newStatus) {
515	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
516	                        shipmentId, newStatus);
517	                return orderShipment;
518	            }
519	
520	            // 상태에 따른 처리
521	            if (newStatus == ShipmentStatus.DELIVERED) {
522	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
523	                        shipmentId, orderShipment.getOrder().getId());
524	
525	                // 배송 상태 업데이트
526	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
527	
528	                // 주문 완료 처리 및 알림
529	                orderService.completeOrder(orderShipment.getOrder().getId());
530	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
531	
532	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
533	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
534	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
535	
536	            } else {
537	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
538	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
539	            }
540	
541	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
542	                    shipmentId, orderShipment.getStatus());
543	
544	            return orderShipment;
545	
546	        } catch (Exception e) {
547	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
548	                    shipmentId, trackingNumber, e.getMessage(), e);
549	
550	            // ShipmentException 타입이 아닌 경우 래핑
551	            if (!(e instanceof ShipmentException)) {
552	                throw new ShipmentException(
553	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
554	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
555	                        e
556	                );
557	            }
558	            throw e;
559	        } finally {
560	            // 페이지 리소스 해제
561	            if (page != null) {
562	                try {
563	                    page.close();
564	                    log.debug("페이지 리소스 해제 완료");
565	                } catch (Exception e) {
566	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
567	                }
568	            }
569	        }
570	    }
