202	@Entity
203	@Getter
204	@NoArgsConstructor
205	@AllArgsConstructor
206	@Builder
207	public class OrderBid extends BaseTimeEntity {
208	
209	    @Id
210	    @GeneratedValue(strategy = GenerationType.IDENTITY)
211	    private Long id;
212	
213	    @ManyToOne(fetch = FetchType.LAZY)
214	    @JoinColumn(name = "user_id")
215	    private User user; // 구매자 정보
216	
217	    @ManyToOne(fetch = FetchType.LAZY)
218	    @JoinColumn(name = "product_size_id")
219	    private ProductSize productSize; // 구매 대상 상품 사이즈
220	
221	    private int bidPrice; // 입찰 가격
222	
223	    @Builder.Default
224	    @Enumerated(EnumType.STRING)
225	    private BidStatus status = BidStatus.PENDING; // 입찰 상태 (대기 중, 매칭 완료 등)
226	
227	    @OneToOne(fetch = FetchType.LAZY)
228	    @JoinColumn(name = "order_id")
229	    private Order order; // 매칭된 구매 엔티티
230	
231	    @OneToOne(fetch = FetchType.LAZY)
232	    @JoinColumn(name = "sale_id")
233	    private Sale sale; // 매칭된 판매 엔티티
234	
235	    // 즉시 구매 플래그
236	    @Builder.Default
237	    @Column(nullable = false)
238	    private boolean isInstantPurchase = false;
239	
240	    /**
241	     * Order와의 양방향 관계를 설정합니다.
242	     * 기존 관계가 있다면 해제하고 새 관계를 설정합니다.
243	     *
244	     * @param order 연결할 Order 객체
245	     */
246	    public void assignOrder(Order order) {
247	        // 기존 관계가 있으면 해제
248	        if (this.order != null && this.order != order) {
249	            Order oldOrder = this.order;
250	            this.order = null;
251	            if (oldOrder.getOrderBid() == this) {
252	                oldOrder.assignOrderBid(null);
253	            }
254	        }
255	
256	        // 새 관계 설정
257	        this.order = order;
258	
259	        // 매칭 상태로 변경
260	        if (order != null) {
261	            this.status = BidStatus.MATCHED;
262	
263	            // Order 쪽에도 관계 설정
264	            if (order.getOrderBid() != this) {
265	                order.assignOrderBid(this);
266	            }
267	        }
268	    }
269	
270	    /**
271	     * Sale과의 양방향 관계를 설정합니다.
272	     *
273	     * @param sale 연결할 Sale 객체
274	     */
275	    public void assignSale(Sale sale) {
276	        this.sale = sale;
277	        this.status = BidStatus.MATCHED;
278	    }
279	
280	    /**
281	     * 즉시 구매로 표시합니다.
282	     */
283	    public void markAsInstantPurchase() {
284	        this.isInstantPurchase = true;
285	    }
286	
287	    /**
288	     * 입찰 상태를 업데이트합니다.
289	     *
290	     * @param newStatus 새 입찰 상태
291	     */
292	    public void updateStatus(BidStatus newStatus) {
293	        this.status = newStatus;
294	    }
295	}package com.fream.back.domain.order.entity;
