 79	public enum SaleStatus {
 80	    PENDING_SHIPMENT,    // 판매자 발송 대기
 81	    IN_TRANSIT,          // 배송 중
 82	    IN_INSPECTION,       // 검수 중
 83	    FAILED_INSPECTION,   // 검수 불합격
 84	    IN_STORAGE,          // 창고 보관 중
 85	    ON_AUCTION,          // 판매 입찰 중
 86	    SELLING,             // 판매중 (등록된 상태)
 87	    SOLD,                // 판매 완료
 88	    AUCTION_EXPIRED;     // 입찰 기한 만료
 89	
 90	    // 상태 전환 규칙
 91	    public boolean canTransitionTo(SaleStatus newStatus) {
 92	        return switch (this) {
 93	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
 94	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
 95	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
 96	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
 97	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
 98	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
 99	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
100	        };
101	    }
